<style>
/* -------------------------------
    DESKTOP MEGA MENU BEHAVIOR
-------------------------------- */
@media (min-width: 1024px) {
    .mega-menu {
        display: none !important;
        position: absolute;
        left: 30%;
        transform: translateX(-50%);
        width: 100vw !important;
        top: 100%;
        z-index: 999;
    }

    /* show on hover (desktop only) */
    .mega-parent:hover .mega-menu {
        display: block !important;
    }
    
    .mega-bg {
    background: #fff;
    width: 100%;
    padding: 40px 0;
    box-shadow: 0 4px 20px rgba(0,0,0,0.1);
}

}

/* -------------------------------
    MOBILE / TABLET BEHAVIOR
-------------------------------- */
@media (max-width: 991px) {
    .mega-menu {
        position: static;
        width: 100%;
        display: none;
    }

    .mega-parent.show .mega-menu {
        display: block !important;
    }

   
    .mega-bg {
    background: #fff;
    width: 100%;
    padding: 20px 10px;
    box-shadow: 0 4px 20px rgba(0,0,0,0.1);
}

}

/* -------------------------------
    MEGA MENU BACKGROUND
-------------------------------- */
.mega-bg {
    background: #fff;
    width: 100%;
    padding: 40px 0;
    box-shadow: 0 4px 20px rgba(0,0,0,0.1);
}

/* -------------------------------
    MEGA MENU ITEMS
-------------------------------- */
.mega-item {
    text-decoration: none;
    color: #333;
    display: block;
    transition: 0.3s ease;
}

.mega-item:hover {
    transform: translateY(-5px);
}

/* -------------------------------
    ICON CIRCLE
-------------------------------- */
.mega-icon {
    width: 60px;
    height: 60px;
    background: #f8f1e7;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: auto;
    overflow: hidden;
}

/* Resize icons on smaller screens */
@media (max-width: 767px) {
    .mega-icon {
        width: 80px;
        height: 80px;
    }
    .mega-bg {
    background: #fff;
    width: 100%;
    padding: 40px 0;
    box-shadow: 0 4px 20px rgba(0,0,0,0.1);
}
}

@media (max-width: 500px) {
    .mega-icon {
        width: 65px;
        height: 65px;
    }
    .mega-bg {
    background: #fff;
    width: 100%;
    padding: 40px 0;
    box-shadow: 0 4px 20px rgba(0,0,0,0.1);
}
}

.mega-icon img {
    width: 75%;
}

/* MEGA MENU: hidden by default */
.mega-menu {
    display: none !important;
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    width: 100vw !important;
    top: 100%;
    z-index: 999;
    padding: 0 !important;
}

/* Show on hover */
.mega-parent:hover .mega-menu {
    display: block !important;
}

/* Full width background */
.mega-bg {
    background: #fff;
    width: 100%;
    padding: 40px 0;
    box-shadow: 0 6px 25px rgba(0,0,0,0.12);
}

/* Category Card */
.mega-item {
    text-decoration: none;
    display: block;
    color: #222;
    transition: 0.3s ease;
}
.mega-item:hover {
    transform: translateY(-5px);
}

/* Circle Image */
.mega-icon {
    width: 100px;
    height: 100px;
    background: #f8f1e7;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 10px;
    overflow: hidden;
}

.mega-icon img {
    width: 90%;
    height: auto;
}

/* Hover show dropdown (Bootstrap normally requires click) */
.nav-item.dropdown:hover .dropdown-menu {
  display: block;
}
</style>




