<script>
document.addEventListener('DOMContentLoaded', function() {
    const input = document.getElementById('mobile_search');

    // 🔸 Multiple placeholder texts to cycle through
    const texts = [
        'Search for "Lokets"',
        'Search for "Shri Yantra"',
        'Search for "Rudraksh"',
        'Search for "Bracelets"',
        'Search for "Shankh"'
    ];

    let textIndex = 0;
    let charIndex = 0;
    let isDeleting = false;

    function typeEffect() {
        const currentText = texts[textIndex];
        if (!isDeleting && charIndex <= currentText.length) {
            // Typing forward
            input.setAttribute('placeholder', currentText.substring(0, charIndex));
            charIndex++;
            setTimeout(typeEffect, 100);
        } 
        else if (isDeleting && charIndex > 0) {
            // Deleting backward
            input.setAttribute('placeholder', currentText.substring(0, charIndex));
            charIndex--;
            setTimeout(typeEffect, 50);
        } 
        else {
            // Switch between typing and deleting
            if (!isDeleting) {
                isDeleting = true;
                setTimeout(typeEffect, 2000); // Pause before deleting
            } else {
                isDeleting = false;
                textIndex = (textIndex + 1) % texts.length; // Next text
                setTimeout(typeEffect, 500); // Pause before next text starts
            }
        }
    }

    typeEffect();
});
</script>


