<style>
#loveyoutooo{
    position: absolute;
    padding: 4px 0px 0px 3px;
    background-color: #ec0826;
    border-radius: 50%;
    width: 30px;
    height: 20px;
    left: 3%;
    top: 11%;
    z-index: 1;
}
.video-wrapper {
    position: relative;
    border-radius: 12px;
    overflow: hidden;
    cursor: pointer;
    transition: transform 0.3s ease;
    
}




/* Slightly smaller non-center items */
.carousel-boxa {
    transform: scale(0.9);
    transition: transform 0.3s ease, z-index 0.3s ease;
    z-index: 1;
 
}

/* Enlarge the center video */
.slick-center .carousel-boxa {
    transform: scale(1.1);
    z-index: 5;
}

/* --- Mute button --- */
.mute-btn {
    position: absolute;
    top: 6%;
    right: 6%;
    background: rgba(0,0,0,0.6);
    border: none;
    border-radius: 6px;
    width: 36px;
    height: 36px;
    display: flex;
    justify-content: center;
    align-items: center;
    color: #fff;
    cursor: pointer;
    transition: background 0.3s;
    z-index: 10;
}
.mute-btn:hover { background: rgba(0,0,0,0.8); }

/* --- Play / Pause button --- */
.play-pause-btn {
    position: absolute;
    top: 6%;
    left: 6%;
    background: rgba(0,0,0,0.6);
    border: none;
    border-radius: 6px;
    width: 36px;
    height: 36px;
    display: flex;
    justify-content: center;
    align-items: center;
    color: #fff;
    cursor: pointer;
    transition: background 0.3s;
    z-index: 10;
}
.play-pause-btn:hover { background: rgba(0,0,0,0.8); }

/* Icon styles */
.icon-volume-mute::before { content: "\1F507"; font-size: 18px; } /* 🔇 */
.icon-volume-up::before   { content: "\1F50A"; font-size: 18px; } /* 🔊 */
.icon-play::before        { content: "\25B6"; font-size: 18px; }  /* ▶️ */
.icon-pause::before       { content: "\23F8"; font-size: 18px; }  /* ⏸ */

/* Product info card (unchanged) */
.product-info {
    display: none;
    position: absolute;
    bottom: 6%;
    left: 5%;
    right: 5%;
    background: rgba(255, 255, 255, 0.95);
    border-radius: 12px;
    padding: 12px;
    opacity: 0;
    transition: opacity 0.3s ease;
}
.slick-center .product-info { display: block; opacity: 1; }
.product-card { font-size: 14px; }
</style>

<script>
document.addEventListener('DOMContentLoaded', function () {
    const carousel = $('#videoCarousel');
    const videos = document.querySelectorAll('.video-slide');

    // Pause all videos
    function pauseAllVideos() {
        videos.forEach(v => v.pause());
    }

    // Play only the center video
    function playCenterVideo() {
        pauseAllVideos();
        document.querySelectorAll('#videoCarousel .slick-slide').forEach(slide => {
            if (slide.classList.contains('slick-center')) {
                const video = slide.querySelector('video');
                if (video) video.play();
            }
        });
    }

    // Initialize carousel
    if (!carousel.hasClass('slick-initialized')) {
        carousel.slick({
            centerMode: true,
            slidesToShow: 6,
            arrows: true,
            infinite: true,
            responsive: [
                { breakpoint: 992, settings: { slidesToShow: 2 } },
                { breakpoint: 576, settings: { slidesToShow: 1, centerMode: false } }
            ]
        });
    }

    // Play on init & after change
    carousel.on('init', playCenterVideo);
    carousel.on('afterChange', playCenterVideo);

    // --- Mute / Unmute ---
    document.addEventListener('click', function(e) {
        if (e.target.closest('.mute-btn')) {
            e.stopPropagation();
            const btn = e.target.closest('.mute-btn');
            const video = btn.closest('.video-wrapper').querySelector('video');
            video.muted = !video.muted;
            btn.innerHTML = video.muted
                ? '<i class="icon-volume-mute"></i>'
                : '<i class="icon-volume-up"></i>';
        }
    });

    // --- Play / Pause toggle ---
    document.addEventListener('click', function(e) {
        if (e.target.closest('.play-pause-btn')) {
            e.stopPropagation();
            const btn = e.target.closest('.play-pause-btn');
            const video = btn.closest('.video-wrapper').querySelector('video');

            if (video.paused) {
                pauseAllVideos();
                video.play();
                btn.innerHTML = '<i class="icon-pause"></i>';
            } else {
                video.pause();
                btn.innerHTML = '<i class="icon-play"></i>';
            }
        }
    });

    // Update play/pause icon based on video state
    videos.forEach(video => {
        const btn = video.closest('.video-wrapper').querySelector('.play-pause-btn');
        video.addEventListener('play', () => { if (btn) btn.innerHTML = '<i class="icon-pause"></i>'; });
        video.addEventListener('pause', () => { if (btn) btn.innerHTML = '<i class="icon-play"></i>'; });
    });
});


</script>

            
            
        </div>
    </div>
</section>


    
    
       
