<style>
    .lab-certification-section {
  padding: 25px 20px;
  background: #fff;
  display: flex;
  justify-content: center;
}

.lab-certification-container {
  display: flex;
  flex-wrap: nowrap;
  max-width: 100%;
  /*width: 100%;*/
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 4px 15px rgba(0,0,0,0.1);
}

/* Left Image */
.lab-image {
  position: relative;
  flex: 1 1 50%;
  background: #f8f8f8;
}

.lab-card-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Badge */
.badge {
  position: absolute;
  top: 20px;
  width: auto;
  left: 12%;
  background: #fff;
  padding: 30px 50px;
  border-radius: 30px;
  display: flex;
  align-items: center;
  box-shadow: 0 2px 6px rgba(0,0,0,0.2);
}

.badge-icon {
  width: 24px;
  margin-right: 8px;
}

.badge-text {
  font-weight: bold;
  color: #000;
  font-size: 18px;
}

/* Right Text */
.lab-text {
  flex: 1 1 50%;
  background: #c97f5f;
  color: #fff;
  padding: 40px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.lab-text .subtitle {
  font-size: 14px;
  letter-spacing: 1px;
  text-transform: uppercase;
  opacity: 0.8;
}

.lab-text .title {
  font-size: 28px;
  font-weight: bold;
  margin: 10px 0;
}

.lab-text .description {
  font-size: 16px;
  line-height: 1.6;
  opacity: 0.95;
}

/* Responsive */
@media (max-width: 768px) {
  .lab-certification-container {
    flex-direction: column;
  }

  .lab-text, .lab-image {
    flex: 1 1 100%;
  }

  .lab-text {
    padding: 30px 20px;
  }
}

</style>

<section class="lab-certification-section">
  <div class="lab-certification-container">
    <!-- Left Side: Image with badge -->
    <div class="lab-image">
      <img src="https://suyagya.com/public/assets/img/laab.webp" alt="Lab Certified Card" class="lab-card-img">
      <div class="badge">
        <img src="https://suyagya.com/public/assets/img/right-tick.webp" alt="Badge Icon" class="badge-icon">
        <span class="badge-text">LAB CERTIFIED</span>
      </div>
    </div>

    <!-- Right Side: Text -->
    <div class="lab-text">
      <h5 class="subtitle">Original Genuine Rudraksha</h5>
      <h2 class="title">Lab Tested & Certified</h2>
      <p class="description">
        Our products are not just beautiful, they are lab-tested and certified, ensuring their authenticity and quality.
      </p>
    </div>
  </div>
</section>




