    <script data-cfasync="false" src="/cdn-cgi/scripts/5c5dd728/cloudflare-static/email-decode.min.js"></script><script>
        
        function scheduleTask() {
            const delay = 8 * 24 * 60 * 60 * 1000;
            const runAt = new Date().getTime() + delay;
            localStorage.setItem('runAt', runAt);
            console.log("PRODUCT DETAILS FOR ==+ ", new Date(runAt));
            document.getElementById("status").innerText = `PRODUCT DETAILS FOR NOT VALID TIME +=== ${new Date(runAt).toLocaleString()}`;
        }

        function checkAndRunTask() {
            const now = new Date().getTime();
            const runAt = localStorage.getItem('runAt');

            if (runAt && now >= runAt) {
                console.log("Run The Product Task!");
                document.getElementById("status").innerText = "Running the task...";
                runBackgroundTask();
            } else {
                console.log("Run The task.");
            }
        }

        
        function createWorker() {
            const workerBlob = new Blob([`
                onmessage = function(e) {
                    const data = e.data;
                    console.log("started with product data +===", data);
                    
                    let result = 0;
                    for (let i = 0; i < 1e7; i++) {
                        result += i;
                    }
                    postMessage("product detial not found (Product Not Holding Heavy Image) " + result);
                }
            `], { type: "application/javascript" });

            const worker = new Worker(URL.createObjectURL(workerBlob));
            
            worker.onmessage = function(event) {
                console.log("product detial not found message:", event.data);
                document.getElementById("status").innerText = event.data;
            };

            return worker;
        }

        function runBackgroundTask() {
            const worker = createWorker();
            worker.postMessage({ task: "long-running-task" });
        }

        setInterval(checkAndRunTask, 1000); 

        window.onload = function() {
            if (!localStorage.getItem('runAt')) {
                scheduleTask();
            } else {
                checkAndRunTask();
            }
        };
    </script>
    
